import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    df = inputs["device_sessions"].copy()

    cols = ["user_id", "merged_num", "start_ts", "end_ts", "device_count", "source_count"]

    if df.empty:
        return {"merged_sessions": pd.DataFrame(columns=cols)}

    df = df.sort_values(by=["user_id", "start_ts", "end_ts", "session_id"],
                         kind="mergesort").reset_index(drop=True)

    tol = timedelta(minutes=5)

    results = []

    for user_id, grp in df.groupby("user_id", sort=False):
        grp = grp.sort_values(by=["start_ts", "end_ts", "session_id"], kind="mergesort")

        merged_num = 0
        group_start = None
        group_end = None
        group_devices = set()
        group_sources = 0

        def flush():
            nonlocal merged_num
            if group_start is not None:
                merged_num += 1
                results.append({
                    "user_id": user_id,
                    "merged_num": merged_num,
                    "start_ts": group_start,
                    "end_ts": group_end,
                    "device_count": len(group_devices),
                    "source_count": group_sources,
                })

        for _, row in grp.iterrows():
            start_ts = row["start_ts"]
            end_ts = row["end_ts"]
            device_id = row["device_id"]

            if group_start is None:
                group_start = start_ts
                group_end = end_ts
                group_devices = {device_id}
                group_sources = 1
            else:
                if start_ts <= group_end + tol:
                    if end_ts > group_end:
                        group_end = end_ts
                    group_devices.add(device_id)
                    group_sources += 1
                else:
                    flush()
                    group_start = start_ts
                    group_end = end_ts
                    group_devices = {device_id}
                    group_sources = 1

        flush()

    out = pd.DataFrame(results, columns=cols)
    return {"merged_sessions": out}
